class Solution {
    public int firstUniqueEven(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        for (int x : nums) cnt.merge(x, 1, Integer::sum);
        for (int x : nums)
            if (x % 2 == 0 && cnt.get(x) == 1) return x;
        return -1;
    }
}

