class Solution {
public:
    int firstUniqueEven(vector<int>& nums) {
        for (int x : nums) {
            if (x % 2) continue;
            int c = 0;
            for (int y : nums) c += (y == x);
            if (c == 1) return x;
        }
        return -1;
    }
};

