class Solution {
    public int firstUniqueEven(int[] nums) {
        for (int x : nums) {
            if (x % 2 != 0) continue;
            int c = 0;
            for (int y : nums) if (y == x) c++;
            if (c == 1) return x;
        }
        return -1;
    }
}

